#include <bits/stdc++.h>
using namespace std;

static char buf[1 << 16];
static size_t blen = 0, bpos = 0;
static inline int gc() {
    if (bpos == blen) {
        blen = fread(buf, 1, sizeof buf, stdin);
        bpos = 0;
        if (!blen) return -1;
    }
    return buf[bpos++];
}
static long long readLong() {
    int c = gc();
    while (c != '-' && (c < '0' || c > '9')) {
        if (c == -1) return 0;
        c = gc();
    }
    bool neg = false;
    if (c == '-') { neg = true; c = gc(); }
    long long v = 0;
    while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
    return neg ? -v : v;
}

struct SplitMix {
    size_t operator()(long long x) const {
        unsigned long long z = (unsigned long long)x + 0x9e3779b97f4a7c15ULL;
        z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
        z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
        return z ^ (z >> 31);
    }
};

int main() {
    int n = (int)readLong(), q = (int)readLong();
    unordered_map<long long, long long, SplitMix> counts;
    counts.reserve(2 * (n + q) + 1);
    long long total = 0;
    for (int i = 0; i < n; i++) {
        long long v = readLong();
        counts[v]++;
        total += v;
    }
    string out;
    for (int i = 0; i < q; i++) {
        long long oldV = readLong(), newV = readLong();
        if (oldV != newV) {
            // Move every copy of old to new; the sum changes by (new - old) per copy.
            auto it = counts.find(oldV);
            long long c = 0;
            if (it != counts.end()) { c = it->second; counts.erase(it); }
            total += (newV - oldV) * c;
            counts[newV] += c;
        }
        out += to_string(total);
        out += '\n';
    }
    if (q == 0) out = "\n";
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int gc() throws IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = gc();
        while (c != '-' && (c < '0' || c > '9')) {
            if (c == -1) return 0;
            c = gc();
        }
        boolean neg = false;
        if (c == '-') { neg = true; c = gc(); }
        long v = 0;
        while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
        return neg ? -v : v;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), q = (int) nextLong();
        HashMap<Long, Long> counts = new HashMap<>(4 * (n + q) + 16);
        long total = 0;
        for (int i = 0; i < n; i++) {
            long v = nextLong();
            counts.merge(v, 1L, Long::sum);
            total += v;
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            long oldV = nextLong(), newV = nextLong();
            if (oldV != newV) {
                // Move every copy of old to new; the sum changes by (new - old) per copy.
                Long c = counts.remove(oldV);
                long cnt = c == null ? 0 : c;
                total += (newV - oldV) * cnt;
                counts.merge(newV, cnt, Long::sum);
            }
            out.append(total).append('\n');
        }
        if (q == 0) out.append('\n');
        PrintStream ps = new PrintStream(new BufferedOutputStream(System.out), false);
        ps.print(out);
        ps.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, err := rd.ReadByte()
	for err == nil && c != '-' && (c < '0' || c > '9') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return 0
	}
	neg := false
	if c == '-' {
		neg = true
		c, err = rd.ReadByte()
	}
	var v int64
	for err == nil && c >= '0' && c <= '9' {
		v = v*10 + int64(c-'0')
		c, err = rd.ReadByte()
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	n, q := int(readInt()), int(readInt())
	counts := make(map[int64]int64, n+q)
	var total int64
	for i := 0; i < n; i++ {
		v := readInt()
		counts[v]++
		total += v
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	var buf []byte
	for i := 0; i < q; i++ {
		oldV, newV := readInt(), readInt()
		if oldV != newV {
			// Move every copy of old to new; the sum changes by (new - old) per copy.
			c := counts[oldV]
			delete(counts, oldV)
			total += (newV - oldV) * c
			counts[newV] += c
		}
		buf = strconv.AppendInt(buf[:0], total, 10)
		buf = append(buf, '\n')
		w.Write(buf)
	}
	if q == 0 {
		w.WriteByte('\n')
	}
}
